    def merge_intervals(intervals):
        if not intervals:
            return []
        intervals = sorted(intervals)
        merged = [intervals[0]]
        for start, end in intervals[1:]:
            if start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
        return merged

    # Filter out empty intervals and merge overlapping ones
    a_valid = [interval for interval in a if interval[0] < interval[1]]
    b_valid = [interval for interval in b if interval[0] < interval[1]]

    a_merged = merge_intervals(a_valid)
    b_merged = merge_intervals(b_valid)

    if not a_merged:
        return []

    result = []

    for a_start, a_end in a_merged:
        current = a_start

        for b_start, b_end in b_merged:
            if b_end <= current or b_start >= a_end:
                continue

            if current < b_start:
                result.append([current, b_start])

            current = max(current, b_end)

        if current < a_end:
            result.append([current, a_end])

    return result

